// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Poppins');

// Load Poppins Bold from Google Fonts at module level
const { fontFamily } = loadFont("normal", {
  weights: ["700"],
});



export type PropertyPassiveIncomeProps = Record<string, any>;

// Helper Component for the Gold Coin
const Coin: React.FC<{
  x: number;
  y: number;
  scale?: number;
  opacity?: number;
  accentColor: string;
  bgColor: string;
}> = ({ x, y, scale = 1, opacity = 1, accentColor, bgColor }) => {
  return (
    <div
      style={{
        position: "absolute",
        left: x - 70,
        top: y - 16,
        width: 140,
        height: 32,
        transform: `scale(${scale})`,
        opacity,
        transition: "none",
      }}
    >
      <svg width="140" height="32" viewBox="0 0 140 32" style={{ overflow: "visible" }}>
        {/* Side depth */}
        <path
          d="M 2 10 A 68 10 0 0 0 138 10 L 138 22 A 68 10 0 0 1 2 22 Z"
          fill={accentColor}
          stroke={bgColor}
          strokeWidth="1.5"
        />
        {/* Ridges on side */}
        {[20, 30, 40, 50, 60, 70, 80, 90, 100, 110, 120].map((rx) => (
          <line
            key={rx}
            x1={rx}
            y1={11}
            x2={rx}
            y2={21}
            stroke="#b39210"
            strokeWidth="1"
            opacity="0.6"
          />
        ))}
        {/* Top Face */}
        <ellipse
          cx="70"
          cy="10"
          rx="68"
          ry="9"
          fill={accentColor}
          stroke={bgColor}
          strokeWidth="1.5"
        />
      </svg>
    </div>
  );
};

const PropertyPassiveIncome: React.FC<PropertyPassiveIncomeProps> = ({
  backgroundColor = "#0d1326",
  transparentBackground = false,
  durationInSeconds = 11,
  primaryColor = "#eecb40",
  accentColor = "#eecb40",
  textColor = "#ffffff",
  titleText = "Your property",
  labelText = "Rental income",
  footerText = "Compounds into passive income",
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Visual layout configurations
  const houseX = width * 0.5;
  const houseY = height * 0.26; // Brought the house closer to the coins (from 0.17 to 0.26)
  const houseWidth = 240;
  const houseHeight = 220;
  const doorBaseY = houseY + 210; // house base Y line

  const stackBaseY = height * 0.78;
  const totalCoins = 24;
  const coinSpacing = 11; // vertical overlapping spacing

  // --- Step 1: Your Property & House Anim (0s - 3s) ---
  const titleOpacity = interpolate(frame, [0, 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [0, 25], [height * 0.08, height * 0.11], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const houseOpacity = interpolate(frame, [15, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const houseOffset = interpolate(frame, [15, 45], [40, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- Step 2: Coin Stack Calculations (3s - 11s) ---
  // We calculate dynamic landing impact bounce using a pure function of frame.
  let activeDip = 0;
  for (let i = 0; i < totalCoins; i++) {
    const spawnFrame = 90 + i * 8;
    const landFrame = spawnFrame + 12;
    if (frame >= landFrame) {
      const age = frame - landFrame;
      if (age >= 0 && age < 10) {
        const amplitude = 3.5 * Math.exp(-age * 0.35);
        activeDip += amplitude * Math.sin(age * 0.7);
      }
    }
  }

  // --- Step 3: Upward Arrow (7s - 8s) ---
  const arrowX = width * 0.5 + 105;
  const arrowBottom = stackBaseY;
  const arrowTopLimit = stackBaseY - totalCoins * coinSpacing - 30;

  const arrowProgress = interpolate(frame, [210, 240], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const arrowEase = arrowProgress * (2 - arrowProgress); // Quad Ease Out
  const arrowCurrentTop = interpolate(arrowEase, [0, 1], [arrowBottom, arrowTopLimit]);

  const arrowHeadOpacity = interpolate(arrowProgress, [0.6, 0.9], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- Step 4: Rental Income Label (3.5s - 4.5s) ---
  const labelOpacity = interpolate(frame, [105, 135], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const labelSlide = interpolate(frame, [105, 135], [-12, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- Step 5: Footer Label (7.6s - 8.6s) ---
  const footerOpacity = interpolate(frame, [230, 260], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const footerY = interpolate(frame, [230, 260], [height * 0.92, height * 0.90], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        color: textColor,
        overflow: "hidden",
      }}
    >
      {/* Title label */}
      <div
        style={{
          position: "absolute",
          top: titleY,
          width: "100%",
          textAlign: "center",
          fontSize: 36,
          fontWeight: 700,
          opacity: titleOpacity,
          letterSpacing: "-0.5px",
          transition: "none",
        }}
      >
        {titleText}
      </div>

      {/* House Frame */}
      <div
        style={{
          position: "absolute",
          top: houseY + houseOffset,
          left: houseX - houseWidth / 2,
          width: houseWidth,
          height: houseHeight,
          opacity: houseOpacity,
          transition: "none",
        }}
      >
        <svg
          width={houseWidth}
          height={houseHeight}
          viewBox="0 0 240 220"
          fill="none"
          stroke={primaryColor}
          strokeWidth="5"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          {/* Chimney connected perfectly to roof slope to avoid overlapping inside */}
          <path d="M 50 75.5 L 50 50 L 65 50 L 65 62.5" />
          {/* Roof */}
          <path d="M 10 110 L 120 15 L 230 110" />
          {/* Base Walls connected precisely to the sloped roof underside */}
          <path d="M 35 88.4 L 35 210 L 205 210 L 205 88.4" />
          {/* Door */}
          <path d="M 100 210 L 100 145 L 140 145 L 140 210" />
        </svg>
      </div>

      {/* Coins Layer (Stretching, falling, and stacked coins) */}
      <div style={{ position: "absolute", width: "100%", height: "100%" }}>
        {Array.from({ length: totalCoins }).map((_, i) => {
          const spawnFrame = 90 + i * 8;
          const landFrame = spawnFrame + 12;

          // Resting Coin
          if (frame >= landFrame) {
            const restingY = stackBaseY - i * coinSpacing + activeDip;
            return (
              <Coin
                key={`stacked-${i}`}
                x={houseX}
                y={restingY}
                accentColor={accentColor}
                bgColor={backgroundColor}
              />
            );
          }

          // Falling Coin
          if (frame >= spawnFrame && frame < landFrame) {
            const progress = (frame - spawnFrame) / 12;
            const easeProgress = progress * progress; // Gravity simulated ease-in
            const targetY = stackBaseY - i * coinSpacing;
            const currentY = interpolate(easeProgress, [0, 1], [doorBaseY, targetY]);

            // Motion trail lines above the falling coin
            const trailY = currentY - 26;
            const trailOpacity = interpolate(progress, [0, 0.3, 0.7, 1], [0, 0.7, 0.5, 0]);

            return (
              <React.Fragment key={`falling-${i}`}>
                {/* 3 thin vertical lines trailing the coin */}
                <svg
                  style={{
                    position: "absolute",
                    left: houseX - 40,
                    top: trailY - 20,
                    width: 80,
                    height: 40,
                    opacity: trailOpacity,
                    transition: "none",
                  }}
                  viewBox="0 0 80 40"
                >
                  <line x1="30" y1="5" x2="30" y2="25" stroke={accentColor} strokeWidth="1.5" />
                  <line x1="40" y1="0" x2="40" y2="30" stroke={accentColor} strokeWidth="1.5" />
                  <line x1="50" y1="5" x2="50" y2="25" stroke={accentColor} strokeWidth="1.5" />
                </svg>

                {/* The Falling Coin */}
                <Coin
                  x={houseX}
                  y={currentY}
                  accentColor={accentColor}
                  bgColor={backgroundColor}
                />
              </React.Fragment>
            );
          }

          return null;
        })}
      </div>

      {/* Upward Gold Arrow */}
      {frame >= 210 && (
        <svg
          style={{
            position: "absolute",
            left: arrowX - 15,
            top: arrowTopLimit - 20,
            width: 30,
            height: arrowBottom - arrowTopLimit + 40,
            transition: "none",
          }}
        >
          {/* Main vertical line drawn upward */}
          <line
            x1="15"
            y1={arrowBottom - arrowTopLimit + 20}
            x2="15"
            y2={arrowCurrentTop - arrowTopLimit + 20}
            stroke={accentColor}
            strokeWidth="3.5"
            strokeLinecap="round"
          />
          {/* Arrowhead */}
          <path
            d={`M 5 28 L 15 18 L 25 28`}
            fill="none"
            stroke={accentColor}
            strokeWidth="3.5"
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{
              opacity: arrowHeadOpacity,
              transform: `translateY(${arrowCurrentTop - arrowTopLimit}px)`,
              transition: "none",
            }}
          />
        </svg>
      )}

      {/* Rental Income label */}
      <div
        style={{
          position: "absolute",
          left: arrowX + 35 + labelSlide,
          top: stackBaseY - (totalCoins * coinSpacing) / 1.6,
          opacity: labelOpacity,
          fontSize: 34,
          fontWeight: 700,
          lineHeight: 1.1,
          textAlign: "left",
          letterSpacing: "-0.5px",
          transition: "none",
        }}
      >
        {labelText.split(" ").map((word, index) => (
          <div key={index}>{word}</div>
        ))}
      </div>

      {/* Footer Text */}
      <div
        style={{
          position: "absolute",
          top: footerY,
          width: "100%",
          textAlign: "center",
          fontSize: 34,
          fontWeight: 700,
          opacity: footerOpacity,
          letterSpacing: "-0.5px",
          transition: "none",
        }}
      >
        {footerText}
      </div>
    </AbsoluteFill>
  );
};

export default PropertyPassiveIncome;